#include <stdio.h>

int main() {
    char s[] = "banana";
    int counts[26] = {0};
    for (int i = 0; s[i] != '\0'; i++) {
        counts[s[i] - 'a']++;
    }
    for (int c = 0; c < 26; c++) {
        if (counts[c] > 0) {
            printf("%c=%d\n", 'a' + c, counts[c]);
        }
    }
    return 0;
}
